+#[test]
+fn a_conditions_wire_must_be_one_the_machine_takes() {
+    let one = |wires: &str, d: &str| with_edm(WIRE, &format!(r#"{{ "wire_diameters": {wires}, "conditions": [ {{ "id": "C1", "wire_diameter": {d} }} ] }}"#));
